// API reports (ADR-0008): each package's built `dist/**/*.d.ts` joined in path order, source-map
// comments removed, compared with the committed `packages/<name>/api-report.d.ts`, so a change to
// a published type is a reviewed diff. Also fails on a forgotten export (a name a module's `.d.ts`
// declares that no entry point exports and that is not `@internal`, which `stripInternal` drops),
// on `export *` in an entry, and on published types that do not compile (an `@internal` name a
// public type still uses). Run after `pnpm build`: `pnpm api` (part of `pnpm check`);
// `pnpm api:update` rewrites the reports. Method: docs/contributing.md, "API reports".

import { spawnSync } from "node:child_process";
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, relative } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

export const PACKAGES = ["core", "view", "react", "docx", "pdf"];

const DECLARED =
  /^export (?:declare )?(?:abstract )?(?:function|class|const|let|var|interface|type|enum|namespace) ([\w$]+)/gm;
const LISTED = /^export (?:type )?\{([^}]*)\}(?: from "[^"]+")?;/gm;

/** The report: each `.d.ts` (`{ path, text }`, posix paths) under its path, in path order. */
export function report(name, files) {
  const parts = [...files]
    .sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0))
    .map(({ path, text }) => {
      const body = text
        .replace(/\r\n/g, "\n")
        .replace(/^\/\/# sourceMappingURL=.*$/m, "")
        .trimEnd();
      return `// ${path}\n${body}\n`;
    });
  return `// API report of ${name}: its published types (dist/**/*.d.ts). Generated by \`pnpm api:update\`; do not edit.\n\n${parts.join("\n")}`;
}

function stripComments(text) {
  return text.replace(/\/\*[\s\S]*?\*\//g, "").replace(/^\s*\/\/.*$/gm, "");
}

/** The modules' names an entry's `export { … }` lists re-export (before `as`). */
function listed(text) {
  const names = [];
  for (const m of stripComments(text).matchAll(LISTED))
    for (const spec of m[1].split(",")) {
      const name = spec
        .trim()
        .replace(/^type\s+/, "")
        .split(/\s+as\s+/)[0];
      if (name) names.push(name);
    }
  return names;
}

/** Names a module declares as exports (not re-exports from another module). */
export function declared(text) {
  const clean = stripComments(text);
  const names = [...clean.matchAll(DECLARED)].map((m) => m[1]);
  for (const m of clean.matchAll(/^export (?:type )?\{([^}]*)\};/gm))
    for (const spec of m[1].split(",")) {
      const name = spec
        .trim()
        .replace(/^type\s+/, "")
        .split(/\s+as\s+/)
        .pop();
      if (name) names.push(name);
    }
  return names;
}

/**
 * Problems with a package's entry points: `export *` in an entry, and names a module declares
 * that no entry exports (`entries`: the entry files' paths).
 */
export function problems(files, entries) {
  const out = [];
  const exported = new Set();
  for (const file of files.filter((f) => entries.includes(f.path))) {
    if (/^export \* from/m.test(stripComments(file.text)))
      out.push(`${file.path}: \`export *\` in an entry; list the names`);
    for (const name of [...listed(file.text), ...declared(file.text)]) exported.add(name);
  }
  for (const file of files.filter((f) => !entries.includes(f.path)))
    for (const name of new Set(declared(file.text)))
      if (!exported.has(name))
        out.push(
          `${file.path}: \`${name}\` is exported by its module but by no entry; export it from an entry or tag it @internal`,
        );
  return out;
}

function dtsFiles(dir, base = dir) {
  return readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) return dtsFiles(path, base);
    return entry.name.endsWith(".d.ts")
      ? [{ path: relative(base, path).replaceAll("\\", "/"), text: readFileSync(path, "utf8") }]
      : [];
  });
}

/** The `.d.ts` files of a package's `exports` entries, relative to `dist`. */
function entryFiles(manifest) {
  return Object.values(manifest.exports)
    .map((target) => (typeof target === "object" ? target.types : undefined))
    .filter((types) => types?.startsWith("./dist/"))
    .map((types) => types.slice("./dist/".length));
}

function main() {
  const root = fileURLToPath(new URL("..", import.meta.url));
  const update = process.argv.includes("--update");
  const failures = [];
  const entryPaths = [];
  for (const pkg of PACKAGES) {
    const dir = join(root, "packages", pkg);
    const manifest = JSON.parse(readFileSync(join(dir, "package.json"), "utf8"));
    const files = dtsFiles(join(dir, "dist"));
    const entries = entryFiles(manifest);
    entryPaths.push(...entries.map((e) => join(dir, "dist", e)));
    failures.push(...problems(files, entries).map((p) => `${manifest.name} ${p}`));
    const text = report(manifest.name, files);
    const committed = join(dir, "api-report.d.ts");
    let previous = null;
    try {
      previous = readFileSync(committed, "utf8").replace(/\r\n/g, "\n");
    } catch {}
    if (update) {
      if (previous !== text) writeFileSync(committed, text);
      console.log(`${manifest.name.padEnd(14)} ${previous === text ? "unchanged" : "written"}`);
    } else if (previous !== text) {
      const temp = join(tmpdir(), `foli-api-${pkg}.d.ts`);
      writeFileSync(temp, text);
      failures.push(
        `${manifest.name}: its API differs from packages/${pkg}/api-report.d.ts (built: ${temp}). ` +
          "Review the change, then run `pnpm api:update` and commit the report.",
      );
    } else console.log(`${manifest.name.padEnd(14)} matches its report`);
  }
  // The published types must compile on their own (skipLibCheck off), as an app's strict build reads them.
  const config = join(tmpdir(), "foli-api-tsconfig.json");
  writeFileSync(
    config,
    JSON.stringify({
      compilerOptions: {
        noEmit: true,
        strict: true,
        skipLibCheck: false,
        module: "NodeNext",
        moduleResolution: "NodeNext",
        target: "ES2022",
        lib: ["ES2022", "DOM", "DOM.Iterable"],
        types: [],
      },
      files: entryPaths,
    }),
  );
  const tsc = spawnSync(
    process.execPath,
    [join(root, "node_modules", "typescript", "bin", "tsc"), "-p", config],
    {
      encoding: "utf8",
    },
  );
  if (tsc.status !== 0)
    failures.push(`the published types do not compile:\n${tsc.stdout}${tsc.stderr}`);
  for (const failure of failures) console.error(failure);
  if (failures.length) process.exit(1);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) main();
